final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: 'Serverless API for content moderation using Rekognition'

Resources:
  ContentModerationApi:
    Type: AWS::ApiGateway::RestApi
    Properties:
      Name: ContentModeration
      EndpointConfiguration:
        Types:
          - REGIONAL

  ContentModerationResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref ContentModerationApi
      ParentId: !GetAtt ContentModerationApi.RootResourceId
      PathPart: '{proxy+}'

  ContentModerationMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref ContentModerationApi
      ResourceId: !Ref ContentModerationResource
      HttpMethod: ANY
      AuthorizationType: NONE
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:aws:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${invokeContentModeration.Arn}/invocations'
        PassthroughBehavior: WHEN_NO_MATCH

  ContentModerationDeployment:
    Type: AWS::ApiGateway::Deployment
    DependsOn:
      - ContentModerationResource
      - ContentModerationMethod
    Properties:
      RestApiId: !Ref ContentModerationApi
      Description: 'Deployment for production stage'

  ContentModerationStage:
    Type: AWS::ApiGateway::Stage
    Properties:
      RestApiId: !Ref ContentModerationApi
      StageName: prod
      DeploymentId: !Ref ContentModerationDeployment
      Description: 'Production stage'

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: invokeContentModerationExecutionRole
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: LambdaExecutionPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: '*'
              - Effect: Allow
                Action:
                  - rekognition:DetectModerationLabels
                Resource: '*'

  invokeContentModeration:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: invokeContentModeration
      Runtime: python3.14
      Handler: index.lambda_handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          import json
          import urllib.request
          import urllib.error
          import boto3
          import os

          rekognition = boto3.client('rekognition')

          def lambda_handler(event, context):
              try:
                  body = event.get('body')
                  if not body:
                      return respond(400, {'error': 'Missing request body'})
                  if isinstance(body, str):
                      try:
                          data = json.loads(body)
                      except json.JSONDecodeError:
                          return respond(400, {'error': 'Invalid JSON in body'})
                  else:
                      data = body

                  url = data.get('url')
                  if not url:
                      return respond(400, {'error': 'Missing url field'})
                  if not url.startswith('http://') and not url.startswith('https://'):
                      return respond(400, {'error': 'Invalid URL'})

                  valid_extensions = ('.jpg', '.jpeg', '.png')
                  if not any(url.lower().endswith(ext) for ext in valid_extensions):
                      return respond(400, {'error': 'Unsupported image format. Only jpg, jpeg, png allowed.'})

                  try:
                      req = urllib.request.Request(url, method='HEAD')
                      with urllib.request.urlopen(req, timeout=10) as response:
                          content_type = response.headers.get('Content-Type', '')
                          content_length = response.headers.get('Content-Length')
                          if content_length:
                              size = int(content_length)
                              if size > 5 * 1024 * 1024:
                                  return respond(400, {'error': 'Image exceeds 5MB size limit'})
                  except urllib.error.HTTPError as e:
                      if e.code == 404:
                          return respond(404, {'error': 'Image not found'})
                      else:
                          return respond(e.code, {'error': f'HTTP error fetching image: {e.code}'})
                  except urllib.error.URLError as e:
                      return respond(400, {'error': f'Network error fetching image: {str(e.reason)}'})

                  try:
                      with urllib.request.urlopen(url, timeout=10) as response:
                          image_data = response.read()
                          if len(image_data) > 5 * 1024 * 1024:
                              return respond(400, {'error': 'Image exceeds 5MB size limit'})
                  except urllib.error.HTTPError as e:
                      if e.code == 404:
                          return respond(404, {'error': 'Image not found'})
                      else:
                          return respond(e.code, {'error': f'HTTP error fetching image: {e.code}'})
                  except urllib.error.URLError as e:
                      return respond(400, {'error': f'Network error fetching image: {str(e.reason)}'})

                  try:
                      response = rekognition.detect_moderation_labels(
                          Image={'Bytes': image_data},
                          MinConfidence=60
                      )
                      moderation_labels = response.get('ModerationLabels', [])
                      labels_output = []
                      for label in moderation_labels:
                          labels_output.append({
                              'Name': label['Name'],
                              'Confidence': label['Confidence'],
                              'ParentName': label.get('ParentName', '')
                          })
                      return respond(200, {'moderationLabels': labels_output})
                  except Exception as e:
                      return respond(500, {'error': f'Rekognition error: {str(e)}'})
              except Exception as e:
                  return respond(500, {'error': f'Internal server error: {str(e)}'})

          def respond(status_code, data):
              return {
                  'statusCode': status_code,
                  'headers': {'Content-Type': 'application/json'},
                  'body': json.dumps(data)
              }

  LambdaInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      FunctionName: !Ref invokeContentModeration
      Action: lambda:InvokeFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:aws:execute-api:${AWS::Region}:${AWS::AccountId}:api/${ContentModerationApi}/*'

AWSTemplateFormatVersion: "2010-09-09"
Description: "Bookstore Cedar policy store with strict schema validation and static Cedar policies."
Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
  AdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Admin", action == Bookstore::Action::"View", resource is Bookstore::Book);
  EveForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid(principal == Bookstore::User::"Eve", action == Bookstore::Action::"View", resource is Bookstore::Book);
  PublisherOwnViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Publisher", action == Bookstore::Action::"View", resource is Bookstore::Book) when { resource.owner == principal };
  AliceSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal == Bookstore::User::"Alice", action == Bookstore::Action::"View", resource == Bookstore::Book::"1984");
  CustomerPremiumAllowedPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource is Bookstore::Book) when { principal.yearsAsMember >= 2 };
  CustomerPremiumForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource is Bookstore::Book) when { principal.yearsAsMember < 2 };
  NonUsRegionForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid(principal, action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"], resource) when { context.region != "US" };
  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Description: The Amazon Verified Permissions policy store ID for the bookstore application.
      Value: !Ref BookstorePolicyStore

AWSTemplateFormatVersion: '2010-09-09'
Description: 'Step Functions Calculator Demo with Lambda and IAM roles'

Resources:
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Tags:
        - Key: Name
          Value: CalculatorDemo

  Calculator:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: Calculator
      Runtime: nodejs24.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!operator || !operands || !Array.isArray(operands) || operands.length !== 2) {
              throw new Error('Invalid input: expected operator and operands array of two numbers');
            }
            const [a, b] = operands;
            if (typeof a !== 'number' || typeof b !== 'number') {
              throw new Error('Operands must be numbers');
            }
            let result;
            switch (operator) {
              case 'add':
                result = a + b;
                break;
              case 'sub':
                result = a - b;
                break;
              case 'mul':
                result = a * b;
                break;
              case 'div':
                if (b === 0) {
                  throw new Error('Division by zero');
                }
                result = a / b;
                break;
              default:
                throw new Error(`Unknown operator: ${operator}`);
            }
            return { result };
          };
      Tags:
        - Key: Name
          Value: CalculatorDemo

  StateMachineExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: InvokeCalculatorLambda
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt Calculator.Arn
      Tags:
        - Key: Name
          Value: CalculatorDemo

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineExecutionRole.Arn
      DefinitionString: !Sub |
        {
          "StartAt": "ChooseOperation",
          "States": {
            "ChooseOperation": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "Add"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "sub",
                  "Next": "Subtract"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "mul",
                  "Next": "Multiply"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "div",
                  "Next": "Divide"
                }
              ],
              "Default": "UnknownOperator"
            },
            "Add": {
              "Type": "Task",
              "Resource": "${Calculator.Arn}",
              "ResultPath": "$.result",
              "Next": "ReturnResult"
            },
            "Subtract": {
              "Type": "Task",
              "Resource": "${Calculator.Arn}",
              "ResultPath": "$.result",
              "Next": "ReturnResult"
            },
            "Multiply": {
              "Type": "Task",
              "Resource": "${Calculator.Arn}",
              "ResultPath": "$.result",
              "Next": "ReturnResult"
            },
            "Divide": {
              "Type": "Task",
              "Resource": "${Calculator.Arn}",
              "ResultPath": "$.result",
              "Next": "ReturnResult"
            },
            "UnknownOperator": {
              "Type": "Fail",
              "Error": "UnknownOperator",
              "Cause": "The operator is not supported. Supported operators: add, sub, mul, div."
            },
            "ReturnResult": {
              "Type": "Pass",
              "End": true
            }
          }
        }
      Tags:
        - Key: Name
          Value: CalculatorDemo

Outputs:
  SampleInputFormat:
    Description: 'Expected input format for the state machine'
    Value: '{"operator": "add", "operands": [1,2]}'

